import{_ as i,l as n,o as t,c as s,v as d,p,x as r,d as l,i as c,S as u,b as e}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"训练确定性","description":"","frontmatter":{"title":"训练确定性","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/training-determinism.md","filePath":"llm/training-determinism.md","lastUpdated":1789023840000}'),E={name:"llm/training-determinism.md"};function m(h,a,A,B,g,f){const o=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=d('<h1 id="训练确定性" tabindex="-1">训练确定性 <a class="header-anchor" href="#训练确定性" aria-label="Permalink to &quot;训练确定性&quot;">​</a></h1><div class="epigraph"><p>同一条命令跑两次得到不同的权重点，不一定是算法随机；浮点结合律、算法选择与未种子化的 dropout，都会把轨迹分叉。</p><footer>—— Pineau et al., Improving Reproducibility in Machine Learning Research, NeurIPS 2021；实现约束见 PyTorch / CUDA 对确定性算法的说明</footer></div><p><a href="/llm/model-soups-averaging">上一课</a>把多检查点平均当成功能。缺口是：若两次名义相同的训练已经不是同一条轨迹，汤与 EMA 的对照实验无法解释。本课写训练期的<strong>确定性来源</strong>，把「种子」从「dropout 的 RNG」扩大到算法、精度与通信。下一课的静默数据损坏是硬件在确定性软件之下仍能改比特的情况；两课不要混。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机性的合法来源：数据 shuffle、dropout、增强、初始化。这些应用同一个种子应可复现。非法或半合法来源：</p><ul><li>GPU 上 <code>atomicAdd</code> 顺序、归约树的结合律：浮点非结合，\\(a+(b+c)\\neq (a+b)+c\\)，多线程归约每次不同。</li><li>非确定性算法：某些卷积、某些 <code>scatter</code> 实现为换速度不保证顺序。</li><li>TF32 / 允许的精度放松：同一 GEMM 两次舍入不同。</li><li>数据加载的 worker 顺序、文件系统枚举未排序。</li><li>All-Reduce 实现与拓扑：多机浮点归约顺序随网络。</li></ul><p>Pineau 等人把可复现性写成研究规范：报告种子、环境、以及哪些操作被设为确定性。LLM 预训练几乎从不全确定——成本不允许关掉最快的核——但<strong>对照实验</strong>必须声明哪一层是锁死的。否则「加了 cap 之后更好」可能是另一条随机轨迹。</p><p><span class="marginnote"><code>torch.manual_seed</code> 不够。还需 CUDA 种子、cuDNN benchmark 关闭或 deterministic 旗标、DataLoader <code>generator</code> 与 <code>worker_init_fn</code>。漏一层，表面种子相同，shuffle 已不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层锁定：</p><ol><li><strong>算法种子：</strong> Python / NumPy / 框架 / CUDA。</li><li><strong>确定性算法：</strong> 打开框架的 deterministic 模式，接受更慢的核。验收：单机、关 TF32、小模型两步，权重逐比特或至少余弦相似度 \\(\\gt 1-10^{-6}\\)。</li><li><strong>精度策略：</strong> 锁 TF32 / BF16 / loss scale，不要「默认随驱动变」。</li><li><strong>数据：</strong> 文件列表排序、shuffle 种子、packing 边界定义。</li><li><strong>通信：</strong> 对照实验尽量同规模、同后端；跨机器的逐比特复现通常放弃，改比「同配方多种子的均值与方差」。</li></ol><p>大模型上把第 2 项全开可能不可接受。实践是：代理模型上全确定以验证代码无未种子化 RNG；大模型上锁 1、3、4，把 2 与 5 当成噪声，用多种子报告。不要假装 70B 两跑会逐比特相同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>dropout 的 RNG 与数据顺序会进入 <a href="/llm/autograd-graph">自动微分</a> 的图：同样的参数，不同的被 drop 的边，VJP 不同，\\(v\\) 不同，之后整条 Adam 轨迹分叉。浮点非结合发生在看似与 RNG 无关的 GEMM 上，即使关掉 dropout 也会分叉。因此「关 dropout 就确定」是错的。FlashAttention 等融合核内部也有归约顺序；确定性模式可能根本没有对应核，只能退回物化注意力。</p><p>与 EMA：两条轻微分叉的轨迹，EMA 后仍分叉，只是差的高频被滤掉一部分。确定性是实验设计，EMA 是估计器，不能互相替代。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不管评测解码的采样随机性——那是推理。也不把确定性当成正确性：两次相同的 NaN 仍是 NaN。下一课 SDC：软件已锁，硬件仍可能翻转位，表现为「不可复现且不可用种子解释」的损失跳变。</p>',17)),(t(),p(u,null,{default:r(()=>[c(o,{id:"mermaid-97",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E5%90%88%E6%B3%95%20RNG%20%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20TR%5B%22%E8%BD%A8%E8%BF%B9%22%5D%0A%20%20ALG%5B%22%E6%A0%B8%E4%B8%8E%E5%BD%92%E7%BA%A6%E9%A1%BA%E5%BA%8F%22%5D%20--%3E%20TR%0A%20%20PREC%5B%22TF32%20%2F%20%E6%B7%B7%E5%90%88%E7%B2%BE%E5%BA%A6%22%5D%20--%3E%20TR%0A%20%20COM%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E5%BD%92%E7%BA%A6%22%5D%20--%3E%20TR%0A%20%20TR%20--%3E%20REP%5B%22%E5%8F%AF%E5%A3%B0%E6%98%8E%E7%9A%84%E5%A4%8D%E7%8E%B0%E7%BA%A7%E5%88%AB%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e("h2",{id:"小结",tabindex:"-1"},[l("小结 "),e("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),a[3]||(a[3]=e("ul",null,[e("li",null,"种子只覆盖合法 RNG；浮点结合律、非确定核、精度与通信都会分叉轨迹。"),e("li",null,"代理模型上追求近逐比特，以抓未种子化 bug；大模型用多种子统计。"),e("li",null,"关 dropout ≠ 确定；融合核可能没有确定性实现。"),e("li",null,"对照实验必须声明锁了哪一层，否则汤与消融无法解释。"),e("li",null,"出处：Pineau et al., NeurIPS 2021；框架对确定性算法的文档。")],-1))])}const N=i(E,[["render",m]]);export{P as __pageData,N as default};
